def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    strongest_prev = 0.0
    bob_prev = 0.0
    urgent_opponents = 0
    rich_opponents = 0

    for oid, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_opponents += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            if bid > strongest_prev:
                strongest_prev = bid
            if oid == 'Bob':
                bob_prev = bid

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    my_urgent = (hp <= 2) or (no_water_days >= 2)
    semi_urgent = (hp <= 4) or (no_water_days >= 1)

    if my_urgent:
        target = max(DAILY_SALARY * 0.92, strongest_prev + 2.0, bob_prev + 1.0)
        return float(min(budget, target))

    if scarcity == 2:
        base = DAILY_SALARY * 0.72
        if rich_opponents >= 1:
            base = max(base, strongest_prev + 1.25)
        if urgent_opponents >= 1:
            base = max(base, DAILY_SALARY * 0.8)
        if semi_urgent:
            base = max(base, DAILY_SALARY * 0.84)
        return float(min(budget, base))

    if scarcity == 1:
        base = DAILY_SALARY * 0.52
        if strongest_prev >= DAILY_SALARY * 0.75:
            base = DAILY_SALARY * 0.38
        elif strongest_prev > 0:
            base = max(base, strongest_prev * 0.9)
        if semi_urgent:
            base = max(base, DAILY_SALARY * 0.62)
        return float(min(budget, base))

    base = DAILY_SALARY * 0.24
    if semi_urgent:
        base = DAILY_SALARY * 0.42
    if strongest_prev >= DAILY_SALARY * 0.85 and hp > 4 and no_water_days == 0:
        base = DAILY_SALARY * 0.18

    if day >= 8 and hp <= 5:
        base = max(base, DAILY_SALARY * 0.5)

    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Reaction to yesterday's pressure: use immediate previous_trace bids
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply tightness heuristic: if supply is near minimum, water is scarce.
    # Aim to win more often when supply is low.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Core bid target: moderate base, escalate with low HP / long no-water streak / tight supply.
    # Exploit: Cindy/Eric used low bids and died; don't mirror their extreme low bids.
    base = DAILY_SALARY * (0.42 + 0.18 * scarcity)

    # If someone previously bid aggressively, slightly increase to avoid being outbid.
    # Alex survived with high bids; treat high previous bid as signal of stronger demand.
    if highest_prev_bid >= DAILY_SALARY * 0.75:
        base *= 1.12

    # Urgency adjustments
    if hp <= 2.0:
        base *= 1.45
    elif hp <= 4.0:
        base *= 1.20

    if no_water_days >= 2:
        base *= 1.25
    elif no_water_days == 1:
        base *= 1.10

    # Convert to final bid with budget cap. Also keep a floor to avoid always losing ties.
    bid = min(budget, base)

    # If budget is very small, still bid something nonzero when HP is critical.
    if bid <= 0.0:
        if hp <= 2.0:
            bid = min(budget, DAILY_SALARY * 0.05)
        else:
            bid = 0.0

    # Safety clamp
    bid = max(0.0, float(bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 50.0

    base_bid = min(my_status['budget'], avg_prev + 5.0)
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    if day_context['supply'] < WATER_REQ * (len(alive_opponents) + 1):
        return min(my_status['budget'], DAILY_SALARY * 0.85)
    return min(my_status['budget'], base_bid)
